import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.Set;

public record OpeningHours(ZoneId zone, Set<DayOfWeek> days, LocalTime opens, LocalTime closes) {
    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter DAY_TIME = DateTimeFormatter.ofPattern("EEE HH:mm", Locale.ENGLISH);

    public boolean isOpen(Instant moment) {
        ZonedDateTime local = moment.atZone(zone);
        LocalTime t = local.toLocalTime();
        return days.contains(local.getDayOfWeek()) && !t.isBefore(opens) && t.isBefore(closes);
    }

    public Instant nextOpening(Instant moment) {
        if (days.isEmpty()) throw new IllegalStateException("the shop never opens");
        if (isOpen(moment)) return moment;
        LocalDate date = moment.atZone(zone).toLocalDate();
        for (int i = 0; i <= 7; i++) {
            LocalDate d = date.plusDays(i);
            if (!days.contains(d.getDayOfWeek())) continue;
            Instant opening = ZonedDateTime.of(d, opens, zone).toInstant();
            if (!opening.isBefore(moment)) return opening;
        }
        throw new IllegalStateException("no opening found within a week");
    }

    public String describe(Instant moment, ZoneId viewer) {
        if (isOpen(moment)) {
            ZonedDateTime closing = ZonedDateTime.of(moment.atZone(zone).toLocalDate(), closes, zone);
            return "open until " + closing.withZoneSameInstant(viewer).format(TIME);
        }
        return "opens " + nextOpening(moment).atZone(viewer).format(DAY_TIME);
    }
}

unitTests:
var weekdays = EnumSet.of(DayOfWeek.MONDAY, DayOfWeek.TUESDAY, DayOfWeek.WEDNESDAY, DayOfWeek.THURSDAY, DayOfWeek.FRIDAY);
var shop = new OpeningHours(ZoneId.of("Europe/Berlin"), weekdays, LocalTime.of(9, 0), LocalTime.of(18, 0));

test("open and closed", () -> {
    check(shop.isOpen(Instant.parse("2026-11-20T08:00:00Z")), "Friday 09:00 in Berlin: open");
    check(!shop.isOpen(Instant.parse("2026-11-20T17:00:00Z")), "Friday 18:00 in Berlin: just closed");
    check(!shop.isOpen(Instant.parse("2026-11-21T10:00:00Z")), "Saturday: closed");
});

test("next opening", () -> {
    checkEq(shop.nextOpening(Instant.parse("2026-11-21T10:00:00Z")), Instant.parse("2026-11-23T08:00:00Z"));
    checkEq(shop.nextOpening(Instant.parse("2026-11-20T06:00:00Z")), Instant.parse("2026-11-20T08:00:00Z"));
    Instant now = Instant.parse("2026-11-20T10:00:00Z");
    checkEq(shop.nextOpening(now), now);
    var never = new OpeningHours(ZoneId.of("UTC"), EnumSet.noneOf(DayOfWeek.class), LocalTime.of(9, 0), LocalTime.of(17, 0));
    checkThrows(IllegalStateException.class, () -> never.nextOpening(now));
});

test("described for the viewer", () -> {
    checkEq(shop.describe(Instant.parse("2026-11-20T10:00:00Z"), ZoneId.of("Europe/London")), "open until 17:00");
    checkEq(shop.describe(Instant.parse("2026-11-21T10:00:00Z"), ZoneId.of("Europe/Berlin")), "opens Mon 09:00");
    checkEq(shop.describe(Instant.parse("2026-11-21T10:00:00Z"), ZoneId.of("America/New_York")), "opens Mon 03:00");
});

